import json
import os

import boto3

codebuild = boto3.client("codebuild")


def build_overrides(repo_url):
    return [
        {
            "name": "RESULTS_BUCKET",
            "value": os.environ["RESULTS_BUCKET"],
            "type": "PLAINTEXT",
        },
        {
            "name": "GRADES_TABLE",
            "value": os.environ["GRADES_TABLE"],
            "type": "PLAINTEXT",
        },
        {
            "name": "GITHUB_TOKEN",
            "value": os.environ["GITHUB_TOKEN_SECRET_ARN"],
            "type": "SECRETS_MANAGER",
        },
        {
            "name": "STUDENT_REPO_URL",
            "value": repo_url,
            "type": "PLAINTEXT",
        },
    ]


def handler(event, context):
    default_repo = os.environ.get("DEFAULT_STUDENT_REPO_URL", "")
    student_repo = default_repo
    source_version = None

    if isinstance(event, dict):
        detail = event.get("detail")
        if isinstance(detail, dict):
            student_repo = detail.get("student_repo_url") or student_repo
            source_version = detail.get("commit") or source_version

        body = event.get("body")
        if body:
            try:
                payload = json.loads(body)
            except (TypeError, ValueError):
                payload = {}
            if isinstance(payload, dict):
                detail = payload.get("detail")
                if isinstance(detail, dict):
                    student_repo = detail.get("student_repo_url") or student_repo
                    source_version = detail.get("commit") or source_version
                student_repo = payload.get("student_repo_url") or student_repo
                source_version = payload.get("commit") or source_version
                repository = payload.get("repository")
                if isinstance(repository, dict):
                    student_repo = (
                        repository.get("clone_url")
                        or repository.get("html_url")
                        or student_repo
                    )

    params = {
        "projectName": os.environ["CODEBUILD_PROJECT_NAME"],
        "environmentVariablesOverride": build_overrides(student_repo or ""),
    }
    if source_version:
        params["sourceVersion"] = str(source_version)

    response = codebuild.start_build(**params)
    build = response.get("build") or {}

    return {
        "statusCode": 202,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(
            {
                "buildId": build.get("id"),
                "studentRepo": student_repo or None,
                "message": "Autograder build started",
            }
        ),
    }

